<span class="line"><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">auto*</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> robot </span><span style="--shiki-light:#D73A49;--shiki-dark:#F97583;">=</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;"> world.</span><span style="--shiki-light:#6F42C1;--shiki-dark:#B392F0;">addArticulatedSystem</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">(urdfPath, </span><span style="--shiki-light:#032F62;--shiki-dark:#9ECBFF;">&quot;&quot;</span><span style="--shiki-light:#24292E;--shiki-dark:#E1E4E8;">, {},</span></span>
